const $=id=>document.getElementById(id);
let renderer;
try { renderer=new THREE.WebGLRenderer({canvas:$('sea'),antialias:true,alpha:false,powerPreference:'high-performance'}); }
catch(e){$('loading').classList.add('gone');$('error').hidden=false;throw e;}
renderer.setPixelRatio(Math.min(window.devicePixelRatio,1.5));
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
renderer.setClearColor('#276e5a');
renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene();
const camera=new THREE.OrthographicCamera(-70,70,45,-45,.1,600);
const ambient=new THREE.HemisphereLight('#a9c8e3','#182a30',1.65);scene.add(ambient);
const sun=new THREE.DirectionalLight('#afc9ef',1.65);sun.position.set(-45,95,30);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-48;sun.shadow.camera.right=48;sun.shadow.camera.top=48;sun.shadow.camera.bottom=-48;sun.shadow.camera.near=1;sun.shadow.camera.far=450;sun.shadow.normalBias=.035;sun.shadow.bias=-.0001;scene.add(sun,sun.target);
const fill=new THREE.DirectionalLight('#7fadc4',.95);fill.position.set(40,30,-40);scene.add(fill);
const atmosphere=new Atmosphere(renderer,scene);
const sea=createSea(ISLANDS),ocean=sea.water;scene.add(ocean);
const debris=new BattleDebris(scene);
const townLife=new TownLife(scene);
const groundScars=new GroundScars(scene);
const powderSmoke=new PowderSmoke(scene);
const bowWaves=new BowWaves();
const islandModels=ISLANDS.map(data=>{const model=makeIsland(data);if(data.kind==='navy-fort'){const fort=model.userData.fortModel;model.userData.damage=fort.userData.damage=new DamageModel(fort,{fort:true});}return model;});islandModels.forEach(model=>scene.add(model));
const buildingModels=new Map();for(const island of islandModels)for(const model of island.userData.buildings){model.userData.damage=new BuildingDamage(model);buildingModels.set(model.userData.building.id,model);}
let state=createState('galleon',Math.floor(Math.random()*1e9)),paused=false,deathPending=false,keys=new Set(),worldTime=0,zoom=1,toastUntil=7,last=0,wakeTimer=0,uiTimer=0;
function buildShip(id,navy=false){const model=makeShipClass(id,navy),c=SHIP_CLASSES[id];model.userData.damage=new DamageModel(model,{width:c.width/model.scale.x,length:c.length/model.scale.z,deck:model.userData.deckHeight||3.7,mainMastZ:model.userData.mainMastZ??.1});return model;}
const fleetModels=new Map();function fleetModel(id){if(!fleetModels.has(id))fleetModels.set(id,buildShip(id));return fleetModels.get(id);}
let player=fleetModel(state.shipClass);scene.add(player);
const playerWake=new ShipWake(scene);
const enemies=state.enemies.map(e=>{const enemyClass=['brig','frigate','galleon'][e.id];e.shipClass=enemyClass;const model=buildShip(enemyClass,true);scene.add(model);const label=document.createElement('div');label.className='world-label enemy';label.innerHTML='<b class=navy-status>ROYAL NAVY</b><span class="enemy-health"><i></i></span>';$('world-labels').append(label);return{model,label,wake:new ShipWake(scene)};});
const cargo=CARGO.map((data,i)=>{const model=makeCargo(i);model.position.set(data.x,0,data.z);scene.add(model);const ring=new THREE.Mesh(new THREE.RingGeometry(2.65,2.685,64),new THREE.MeshBasicMaterial({color:'#e1d5a5',transparent:true,opacity:.22,side:THREE.DoubleSide,depthWrite:false}));ring.userData.waterSurface=true;ring.rotation.x=-Math.PI/2;ring.position.set(data.x,-.03,data.z);scene.add(ring);const label=document.createElement('div');label.className='world-label treasure';label.textContent='♢';$('world-labels').append(label);return{model,ring,label};});
const islandLabels=ISLANDS.map(i=>{const label=document.createElement('div');label.className='world-label port '+i.kind;label.textContent='⚑ '+i.name+' · '+(i.kind==='navy-fort'?'ROYAL NAVY':i.kind==='black-market'?'BLACK MARKET':i.kind==='pirate-port'?'FREE PORT':'SETTLEMENT');$('world-labels').append(label);return label;});
const targetMarker=new THREE.Mesh(new THREE.RingGeometry(1.6,1.8,32),new THREE.MeshBasicMaterial({color:'#f6e8bb',transparent:true,opacity:.7,side:THREE.DoubleSide,depthWrite:false}));targetMarker.userData.waterSurface=true;targetMarker.rotation.x=-Math.PI/2;targetMarker.visible=false;scene.add(targetMarker);
const particles=[],maxParticles=1100,particleDummy=new THREE.Object3D(),particleColor=new THREE.Color();
const particleGeometry=new THREE.BoxGeometry(1,1,1),particleAlpha=new THREE.InstancedBufferAttribute(new Float32Array(maxParticles),1);particleGeometry.setAttribute('instanceOpacity',particleAlpha);
const particleMaterial=new THREE.MeshBasicMaterial({color:'#ffffff',transparent:true,opacity:1,depthWrite:false});particleMaterial.onBeforeCompile=shader=>{shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nattribute float instanceOpacity;varying float vInstanceOpacity;').replace('#include <begin_vertex>','#include <begin_vertex>\nvInstanceOpacity=instanceOpacity;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying float vInstanceOpacity;').replace('#include <color_fragment>','#include <color_fragment>\ndiffuseColor.a*=vInstanceOpacity;');};
const particleMesh=new THREE.InstancedMesh(particleGeometry,particleMaterial,maxParticles);particleMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);particleMesh.frustumCulled=false;particleMesh.count=0;scene.add(particleMesh);
const cannonMesh=new THREE.InstancedMesh(new THREE.BoxGeometry(.45,.45,.45),new THREE.MeshLambertMaterial({color:'#34352a'}),100);cannonMesh.frustumCulled=false;cannonMesh.count=0;scene.add(cannonMesh);
const birds=new THREE.Group();for(let i=0;i<6;i++){const bird=new THREE.Group();for(const side of [-1,1]){const wing=new THREE.Mesh(new THREE.BoxGeometry(.9,.08,.23),new THREE.MeshBasicMaterial({color:'#e0e2ca'}));wing.position.x=side*.38;wing.rotation.z=side*.2;bird.add(wing);}bird.userData.phase=i*1.76;birds.add(bird);}scene.add(birds);
const projection=new THREE.Vector3(),raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),seaPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),hit=new THREE.Vector3();
const follow=new THREE.Vector3(state.x,0,state.z),offset=new THREE.Vector3(60,105,80),cameraLook=new THREE.Vector3();
let screenW=window.innerWidth,screenH=window.innerHeight;
function resize(){screenW=window.innerWidth;screenH=window.innerHeight;renderer.setSize(screenW,screenH,false);const height=(screenW<600?83:64)*zoom;const aspect=screenW/screenH;camera.left=-height*aspect/2;camera.right=height*aspect/2;camera.top=height/2;camera.bottom=-height/2;camera.updateProjectionMatrix();const shadowSpan=Math.max(48,height*.95);Object.assign(sun.shadow.camera,{left:-shadowSpan,right:shadowSpan,top:shadowSpan,bottom:-shadowSpan});sun.shadow.camera.updateProjectionMatrix();sea.resize(screenW,screenH);atmosphere.resize(screenW,screenH);}
window.addEventListener('resize',resize);resize();
function particle(x,y,z,vx,vy,vz,color,size,life,kind='debris'){if(particles.length<maxParticles)particles.push({x,y,z,vx,vy,vz,color,size,life,max:life,kind});}
function burst(x,z,type){const smoke=type==='fire',gold=type==='cargo',hit=type==='hit'||type==='sunk';for(let i=0;i<(smoke?24:gold?35:hit?38:12);i++){const a=Math.random()*Math.PI*2,v=Math.random()*(hit?5:3),life=smoke?1.5:gold?1.3:1;particle(x,smoke?2:1,z,Math.cos(a)*v,smoke?1.5+Math.random()*2:2+Math.random()*5,Math.sin(a)*v,smoke?'#ddd9bd':gold?'#f3cb6d':hit?i%3?'#9f6b3e':'#f6d69a':'#c5ead1',smoke?.7:gold?.3:.35,life+Math.random()*.5);}}
function toast(text,duration=4){$('toast').textContent=text;$('toast').classList.remove('hidden');toastUntil=worldTime+duration;}
function cannonSmoke(e){powderSmoke.fire(e);}
function sprayAtBow(body,spec,pose){
 const e=bowWaves.update(body,spec,pose,worldTime);if(!e)return;
 for(const side of [-1,1])for(let i=0;i<3+Math.ceil(e.strength*5);i++){
  const outward=side*(1.0+Math.random()*(1.8+e.strength)),forward=e.speed*.30;
  particle(e.x-e.fz*side*e.beam,e.y+Math.random()*.18,e.z+e.fx*side*e.beam,e.fx*forward-e.fz*outward,1.1+Math.random()*(1.6+e.strength*2.3),e.fz*forward+e.fx*outward,i%3?'#a9d1c5':'#e0e9d5',.08+Math.random()*.13,.65+Math.random()*.6,'spray');
 }
}
let soundEnabled=false,audioContext=null,seaNoise=null;
function enableSound(){if(!audioContext)audioContext=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();if(!seaNoise){const buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate),data=buffer.getChannelData(0);let prev=0;for(let i=0;i<data.length;i++){prev=(prev+Math.random()*.04-.02)/1.015;data[i]=prev;}const src=audioContext.createBufferSource();src.buffer=buffer;src.loop=true;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=450;const gain=audioContext.createGain();gain.gain.value=.13;src.connect(filter).connect(gain).connect(audioContext.destination);src.start();seaNoise=gain;}seaNoise.gain.setTargetAtTime(soundEnabled?.13:0,audioContext.currentTime,.1);}
function audioEffect(type){if(!soundEnabled||!audioContext)return;const t=audioContext.currentTime,gain=audioContext.createGain();gain.connect(audioContext.destination);if(type==='cannon'||type==='hit'||type==='sunk'){const length=audioContext.sampleRate*.7,buffer=audioContext.createBuffer(1,length,audioContext.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*Math.exp(-i/length*6);const src=audioContext.createBufferSource();src.buffer=buffer;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.setValueAtTime(type==='cannon'?460:350,t);src.connect(filter).connect(gain);gain.gain.value=type==='cannon'?.085:.12;src.start();}else{const osc=audioContext.createOscillator();osc.type='sine';osc.frequency.setValueAtTime(523,t);osc.frequency.setValueAtTime(659,t+.1);osc.frequency.setValueAtTime(784,t+.2);gain.gain.setValueAtTime(.10,t);gain.gain.exponentialRampToValueAtTime(.001,t+.5);osc.connect(gain);osc.start();osc.stop(t+.5);}}
function toggleSound(){soundEnabled=!soundEnabled;enableSound();$('sound').textContent=soundEnabled?'♪':'♫';$('sound').setAttribute('aria-label',soundEnabled?'Mute sound':'Enable sound');$('sound').setAttribute('aria-pressed',String(soundEnabled));toast(soundEnabled?'Listen to the sea.':'Sound muted.',2);}
$('sound').addEventListener('click',toggleSound);
function sails(value){if(paused)return;setSails(state,value);if(state.status==='playing')toast(['Sails furled. Drifting to a stop.','Quarter sail. Easy does it.','Half sail. A steady course.','Full sail. Let her run!'][state.throttle],2.4);updateUI();}
function fire(side='auto'){if(paused)return;if(fireBroadside(state,side)){updateUI();}else if(state.cooldown>0)toast('Powder and shot! The crew is reloading.',1.5);}
function repairShip(){if(paused)return;if(repair(state))updateUI();else if(!nearestHarbor(state))toast('Repairs are available at friendly harbours.');else if(state.hull>=100)toast('Your ship is already seaworthy.');else toast(`Repairs cost ${nearestHarbor(state)?.repairCost||100} doubloons.`);}
$('sails').onclick=()=>sails((state.throttle+1)%4);$('fire').onclick=()=>fire();$('repair').onclick=repairShip;
function showModal(type){const resetScroll=!$('modal').open||$('modal').dataset.view!==type;$('modal').dataset.view=type;$('modal').classList.toggle('fleet-modal',type==='fleet');$('modal').classList.toggle('shop-modal',type==='shop'||type==='dev');keys.clear();paused=true;$('pause').textContent='▷';$('pause').setAttribute('aria-label','Resume game');const c=$('modal-content');if(type==='fleet'){showFleet(c);}else if(type==='harbor'){showHarbor(c);}else if(type==='shop'){showShop(c);}else if(type==='dev'){showDevMenu(c);}else if(type==='help'){c.innerHTML=`<div class="eyebrow">THE CAPTAIN’S GUIDE</div><h2>Make your own fortune.</h2><p>Take the helm of your ship. Recover five floating salvage bundles, sink two royal navy patrols, and return to the free port of Nassau.</p><div class="guide-row"><span>Raise / lower sails</span><span><kbd>W</kbd> <kbd>S</kbd></span></div><div class="guide-row"><span>Turn port / starboard</span><span><kbd>A</kbd> <kbd>D</kbd></span></div><div class="guide-row"><span>Fire nearest broadside</span><kbd>SPACE</kbd></div><div class="guide-row"><span>Fire port / starboard guns</span><span><kbd>Q</kbd> <kbd>E</kbd></span></div><div class="guide-row"><span>Choose ship / harbour services</span><span><kbd>B</kbd> <kbd>F</kbd></span></div><div class="guide-row"><span>Chart / pause / repair in port</span><span><kbd>M</kbd> <kbd>P</kbd> <kbd>R</kbd></span></div><div class="guide-row"><span>Hide UI / developer menu</span><span><kbd>U</kbd> <kbd>F2</kbd></span></div><div class="guide-row"><span>Upgrade shop / zoom</span><span><kbd>O</kbd> Scroll</span></div><div class="guide-row"><span>False colours / hoist pirate flag</span><kbd>C</kbd></div><p>Fly a red ensign before approaching an unaware patrol. Hoist the Jolly Roger for 3.5 seconds of surprise. Firing reveals you automatically; witnesses remember your ship even if you change flags.</p><p>Click open water to set a course. Sail close to cargo to collect it. Bring an enemy alongside at close range to land a broadside. Fire Q or E with your broadside facing a settlement to damage its buildings. Walls break and roofs collapse under repeated hits. Mind the shallows!</p><button class="primary" id="resume">Back to the helm</button>`;}else if(type==='map'){c.innerHTML=`<div class="eyebrow">A CHART OF</div><h2>The Bahama Islands</h2><canvas id="bigmap" width="600" height="600" aria-label="Interactive navigation chart"></canvas><div class="chart-legend"><span>▲ Your ship</span><span>◆ Lost cargo</span><span>● Navy patrol</span><span>⚑ Nassau</span></div><p>Click open water on the chart to set your course.</p><button class="primary" id="resume">Back to the helm</button>`;$('bigmap').addEventListener('click',chartClick);drawMap($('bigmap'),true);}else if(type==='won'||type==='lost'){const won=type==='won';c.innerHTML=`<div class="eyebrow">${won?'VOYAGE COMPLETE':'A CAPTAIN GOES DOWN WITH THE SHIP'}</div><h2>${won?'A fortune, hard won.':'Claimed by the Caribbean.'}</h2><p>${won?'The taverns of Nassau will be telling your story tonight. Your cargo is safe, the Crown is poorer, and your crew has earned its share.':`${SHIP_CLASSES[state.shipClass].title} rests beneath the waves. There is always another ship, another crew, and another chance at fortune.`}</p><div class="guide-row"><span>Doubloons earned</span><strong>◈ ${state.gold.toLocaleString()}</strong></div><div class="guide-row"><span>Cargo recovered</span><strong>${state.cargo}</strong></div><div class="guide-row"><span>Navy ships sunk</span><strong>${state.sunk}</strong></div><button class="primary" id="restart">Sail again</button>`;$('restart').onclick=restart;}else{c.innerHTML=`<div class="eyebrow">AT ANCHOR</div><h2>A moment of calm.</h2><p>Your voyage is paused. The Caribbean can wait.</p><button class="primary" id="resume">Back to the helm</button><button class="repair" id="paused-help">Captain’s guide</button>`;$('paused-help').onclick=()=>showModal('help');}if($('resume'))$('resume').onclick=closeModal;if(!$('modal').open)$('modal').showModal();if(resetScroll)$('modal').scrollTop=0;}
function closeModal(){$('modal').close();paused=state.status!=='playing'&&!deathPending;$('pause').textContent=paused?'▷':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume game':'Pause game');$('sea').focus({preventScroll:true});}
function showHarbor(content){
  const harbor=nearestHarbor(state);if(!harbor){content.innerHTML='<h2>A harbour lies ahead.</h2><p>Sail closer to a friendly port to come ashore.</p><button class="primary" id="resume">Back to the helm</button>';return;}
  const market=harbor.kind==='black-market';
  content.innerHTML=`<div class="eyebrow">${market?'NO QUESTIONS ASKED':harbor.kind==='pirate-port'?'THE PIRATE REPUBLIC':'A FRIENDLY PORT OF CALL'}</div><h2>${harbor.name}</h2><p>${market?'Contraband, fine powder, and a discreet shipwright. Every captain has a price.':harbor.kind==='pirate-port'?'A free harbour for captains who answer to no crown.':'The shipwright can mend your timbers while the crew takes shore leave.'}</p><div class="harbor-balance">YOUR PURSE <strong>◈ ${state.gold.toLocaleString()}</strong></div><button class="harbor-service" id="harbor-repair" ${state.hull>=100||state.gold<harbor.repairCost?'disabled':''}><span><strong>Repair the hull</strong><small>${state.hull>=100?'Your ship is already seaworthy.':'Restore hull integrity to 100%.'}</small></span><b>◈ ${harbor.repairCost}</b></button><button class="harbor-service" id="harbor-shop"><span><strong>Outfit your ship</strong><small>Hull, sails, rigging, powder and gun crews.</small></span><b>UPGRADES ↗</b></button><button class="harbor-service" id="harbor-fleet"><span><strong>Visit the shipwright</strong><small>Change your ship class.</small></span><b>↗</b></button><button class="primary" id="resume">Return to your ship</button>`;
  $('harbor-repair').onclick=()=>{if(repair(state)){handleEvents();updateUI();showModal('harbor');}};
  $('harbor-shop').onclick=()=>showModal('shop');
  $('harbor-fleet').onclick=()=>showModal('fleet');
}
function upgradeSummary(){const e=upgradeEffects(state);return `<div class="upgrade-summary"><span><b>+${Math.round((e.hull-1)*100)}%</b>HULL</span><span><b>+${Math.round((e.speed-1)*100)}%</b>SPEED</span><span><b>+${Math.round((e.handling-1)*100)}%</b>HANDLING</span><span><b>${(RELOAD_TIME*e.reload).toFixed(1)}s</b>RELOAD</span></div>`;}
function showShop(content){
 const port=nearestHarbor(state),playing=state.status==='playing';
 content.innerHTML=`<div class="eyebrow">THE SHIPWRIGHT’S WORKSHOP</div><h2>Ready for the next broadside.</h2><p>${port?port.name+' · Upgrades fitted while you are at anchor.':'Browse the workshop. Sail to a friendly harbour to fit upgrades.'}<br>Fittings stay with you when you change ships, for this voyage.</p><div class="harbor-balance">YOUR PURSE <strong>◈ ${state.gold.toLocaleString()}</strong></div>${upgradeSummary()}<div class="upgrade-grid">${Object.entries(UPGRADES).map(([id,u])=>{const level=upgradeLevel(state,id),cost=u.costs[level],max=cost===undefined;return `<article class="upgrade-card"><div class="upgrade-heading"><span>${u.category}</span><span>${level} / ${u.costs.length}</span></div><h3>${u.name}</h3><p>${u.description}</p><strong>${u.effect}</strong><div class="upgrade-pips" aria-label="Level ${level} of ${u.costs.length}">${u.costs.map((_,i)=>`<i class="${i<level?'filled':''}"></i>`).join('')}</div><button class="upgrade-buy" data-upgrade="${id}" ${!playing||!port||max||state.gold<cost?'disabled':''}>${max?'Fully upgraded':!port?'Available in harbour':state.gold<cost?'Need ◈ '+cost:'Fit level '+(level+1)+' · ◈ '+cost}</button></article>`;}).join('')}</div><button class="primary" id="resume">Back to the helm</button>`;
 content.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(buyUpgrade(state,b.dataset.upgrade)){handleEvents();updateUI();showModal('shop');}});
}
function weatherControls(){return `<section class="weather-controls"><h3>Weather & sea state</h3><p>Live preview behind this menu. High waves lift and roll the ships.</p><div class="dev-actions">${Object.keys(WEATHER_PRESETS).map(id=>`<button data-weather-preset="${id}">${id[0].toUpperCase()+id.slice(1)}</button>`).join('')}</div>${[['waves','Wave intensity',3],['wind','Wind strength',3],['rain','Rain',1]].map(([key,label,max])=>`<label for="weather-${key}"><span>${label}</span><output id="weather-${key}-value">${seaState[key].toFixed(2)}</output><input type="range" id="weather-${key}" data-weather="${key}" min="0" max="${max}" step="0.05" value="${seaState[key]}" /></label>`).join('')}</section>`;}
function showDevMenu(content){
 content.innerHTML=`<div class="eyebrow">DEVELOPER TOOLS · F2</div><h2>The captain’s sandbox.</h2><p>Adjust the sea, grant fittings, repair your ship, or jump to a harbour.</p>${weatherControls()}<div class="harbor-balance">YOUR PURSE <strong>◈ ${state.gold.toLocaleString()}</strong></div>${upgradeSummary()}<div class="dev-actions"><button data-dev="gold">Give 1,000 doubloons</button><button data-dev="repair">Repair ship</button><button data-dev="max">Grant all upgrades</button><button data-dev="reset">Remove upgrades</button></div><div class="dev-upgrades">${Object.entries(UPGRADES).map(([id,u])=>`<button class="harbor-service" data-grant="${id}" ${upgradeLevel(state,id)>=u.costs.length?'disabled':''}><span><strong>${u.name}</strong><small>${u.effect}</small></span><b>${upgradeLevel(state,id)} / ${u.costs.length} · GRANT +1</b></button>`).join('')}</div><h3 class="dev-subheading">Evacuation previews</h3><div class="dev-actions"><button data-dev="evacuate">Evacuate nearby town</button><button data-dev="abandon">Abandon nearest enemy ship</button></div><p>Resume to watch. Ship abandonment is normally a 12% chance below 28% hull.</p><h3 class="dev-subheading">Go to a harbour</h3><div class="dev-actions">${ISLANDS.filter(i=>i.port).map(i=>`<button data-harbor="${i.seed}">${i.name}</button>`).join('')}</div><button class="primary" id="dev-shop">Open upgrade shop</button><button class="repair" id="resume">Back to the helm</button>`;
 const apply=(action,id)=>{if(devAction(state,action,id)){if(action==='harbor'){playerWake.clear();follow.set(state.x,0,state.z);}handleEvents();updateUI();showModal('dev');}};
 content.querySelectorAll('[data-dev]').forEach(b=>b.onclick=()=>apply(b.dataset.dev));
 content.querySelectorAll('[data-grant]').forEach(b=>b.onclick=()=>apply('upgrade',b.dataset.grant));
 content.querySelectorAll('[data-harbor]').forEach(b=>b.onclick=()=>apply('harbor',b.dataset.harbor));
 content.querySelectorAll('[data-weather]').forEach(input=>input.oninput=()=>{setWeather({[input.dataset.weather]:Number(input.value)});$('weather-'+input.dataset.weather+'-value').value=Number(input.value).toFixed(2);});
 content.querySelectorAll('[data-weather-preset]').forEach(button=>button.onclick=()=>{setWeather(WEATHER_PRESETS[button.dataset.weatherPreset]);showModal('dev');});
 $('dev-shop').onclick=()=>showModal('shop');
}
function toggleUI(){
 const hidden=$('game').classList.toggle('ui-hidden');
 $('ui-toggle').textContent=hidden?'Show UI [U]':'Hide UI [U]';$('ui-toggle').setAttribute('aria-pressed',String(hidden));
 for(const el of document.querySelectorAll('.topbar,.voyage,.wind,.ship-panel,.center-bottom,.map-panel,.touch-steer'))el.inert=hidden;
 $('sea').focus({preventScroll:true});
}
