window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if((e.ctrlKey||e.metaKey||e.altKey)||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))return;if(e.repeat&&['KeyC','KeyU','F2','KeyO','KeyB','KeyF','KeyH','KeyW','KeyS','ArrowUp','ArrowDown','KeyM','KeyP','Escape','KeyR'].includes(e.code))return;if(e.code==='F2'){e.preventDefault();showModal('dev');return;}if(e.code==='KeyU'&&!$('modal').open){toggleUI();return;}if(e.code==='KeyP'||e.code==='Escape'){if($('modal').open)closeModal();else showModal('pause');return;}if($('modal').open){if(e.code==='KeyM')closeModal();return;}keys.add(e.code);if(e.code==='KeyW'||e.code==='ArrowUp')sails(state.throttle+1);if(e.code==='KeyS'||e.code==='ArrowDown')sails(state.throttle-1);if(e.code==='Space')fire();if(e.code==='KeyC')changeColours();if(e.code==='KeyQ')fire('port');if(e.code==='KeyE')fire('starboard');if(e.code==='KeyR')repairShip();if(e.code==='KeyM')showModal('map');if(e.code==='KeyH')showModal('help');if(e.code==='KeyB')showModal('fleet');if(e.code==='KeyO')showModal('shop');if(e.code==='KeyF'){if(nearestHarbor(state))showModal('harbor');else toast('Sail to a friendly harbour to come ashore.');}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();last=0;});
document.querySelectorAll('[data-key]').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(btn.dataset.key);btn.setPointerCapture(e.pointerId);});for(const event of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(event,()=>keys.delete(btn.dataset.key));});
function navigate(x,z){if(ISLANDS.some(i=>Math.hypot(x-i.x,z-i.z)<coastRadius(i,Math.atan2(z-i.z,x-i.x))+4)){toast('Land ahead. Choose a course through open water.');return false;}steerTo(state,x,z);toast('Course set. Mind the islands along the way.',2.5);updateUI();return true;}
$('sea').addEventListener('pointerdown',e=>{if(paused||state.status!=='playing')return;pointer.set(e.clientX/screenW*2-1,-e.clientY/screenH*2+1);raycaster.setFromCamera(pointer,camera);if(raycaster.ray.intersectPlane(seaPlane,hit))navigate(hit.x,hit.z);$('sea').focus({preventScroll:true});});
$('sea').addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.7,Math.min(2.8,zoom+e.deltaY*.0007));resize();},{passive:false});
function chartClick(e){const rect=e.currentTarget.getBoundingClientRect();const x=((e.clientX-rect.left)/rect.width-.5)*(WORLD_LIMIT*2+30),z=((e.clientY-rect.top)/rect.height-.5)*(WORLD_LIMIT*2+30);if(navigate(x,z))closeModal();}
function drawMap(canvas,big=false){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,scale=(big?Math.min(w,h):Math.min(w,h)*1.6)/(WORLD_LIMIT*2+30),cx=big?0:state.x*.25,cz=big?0:state.z*.25;const X=x=>w/2+(x-cx)*scale,Z=z=>h/2+(z-cz)*scale;ctx.fillStyle='#173c34';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#779a6d19';ctx.lineWidth=1;for(let i=-WORLD_LIMIT;i<=WORLD_LIMIT;i+=40){ctx.beginPath();ctx.moveTo(X(i),0);ctx.lineTo(X(i),h);ctx.stroke();ctx.beginPath();ctx.moveTo(0,Z(i));ctx.lineTo(w,Z(i));ctx.stroke();}ctx.strokeStyle='#a5ac7b33';ctx.setLineDash([3,5]);ctx.strokeRect(X(-WORLD_LIMIT),Z(-WORLD_LIMIT),WORLD_LIMIT*2*scale,WORLD_LIMIT*2*scale);ctx.setLineDash([]);ISLANDS.forEach((island,i)=>{ctx.beginPath();for(let j=0;j<64;j++){const a=j/64*Math.PI*2,r=coastRadius(island,a);const x=X(island.x+Math.cos(a)*r),z=Z(island.z+Math.sin(a)*r);j?ctx.lineTo(x,z):ctx.moveTo(x,z);}ctx.closePath();ctx.fillStyle='#74815a';ctx.fill();ctx.strokeStyle='#b0ae73';ctx.stroke();if(big||island===PORT){ctx.fillStyle='#c8c69c';ctx.font=`${big?13:8}px Georgia`;ctx.textAlign='center';ctx.fillText(island.name,X(island.x),Z(island.z)+island.r*scale+(big?17:10));}});CARGO.forEach((c,i)=>{if(state.collected.has(i))return;ctx.fillStyle='#d7b771';ctx.save();ctx.translate(X(c.x),Z(c.z));ctx.rotate(Math.PI/4);ctx.fillRect(-2,-2,4,4);ctx.restore();});state.enemies.filter(e=>e.hull>0).forEach(e=>{ctx.fillStyle='#d08762';ctx.beginPath();ctx.arc(X(e.x),Z(e.z),big?4:2.5,0,Math.PI*2);ctx.fill();});if(state.target){ctx.strokeStyle='#ddd5aa77';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(X(state.x),Z(state.z));ctx.lineTo(X(state.target.x),Z(state.target.z));ctx.stroke();ctx.setLineDash([]);}ctx.save();ctx.translate(X(state.x),Z(state.z));ctx.rotate(state.angle);ctx.fillStyle='#f1e7bf';ctx.shadowColor='#f3e5a9';ctx.shadowBlur=6;ctx.beginPath();ctx.moveTo(0,-7);ctx.lineTo(4.5,5);ctx.lineTo(0,3);ctx.lineTo(-4.5,5);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='#d0c8a2';ctx.font=`${big?15:10}px Georgia`;ctx.textAlign='center';ctx.fillText('N',w-18,18);ctx.strokeStyle='#bdc29c77';ctx.beginPath();ctx.moveTo(w-18,23);ctx.lineTo(w-18,37);ctx.moveTo(w-22,28);ctx.lineTo(w-18,23);ctx.lineTo(w-14,28);ctx.stroke();}
function projectLabel(label,x,y,z){projection.set(x,y,z).project(camera);const px=(projection.x*.5+.5)*screenW,py=(-projection.y*.5+.5)*screenH;label.style.left=`${px}px`;label.style.top=`${py}px`;label.style.display=Math.abs(projection.x)>1.1||Math.abs(projection.y)>1.1?'none':'block';}
function weatherWind(){return .5+.5*Math.sin(worldTime*.025-.45);}
function updateUI(){const falseFlag=state.colours==='navy',recognized=[...state.enemies,...state.forts].some(e=>e.hull>0&&e.alerted&&Math.hypot(e.x-state.x,e.z-state.z)<110);$('colours-button').textContent=falseFlag?'⚑ Hoist the colours [C]':'⚑ Fly false colours [C]';$('colours-button').setAttribute('aria-pressed',String(falseFlag));$('colours-status').textContent=falseFlag?(recognized?'RED ENSIGN · RECOGNIZED':'RED ENSIGN · DISGUISED'):'JOLLY ROGER · PIRATE COLOURS';const spec=SHIP_CLASSES[state.shipClass];$('ship-name').textContent=spec.title;$('cannon-count').textContent=state.disabledGuns?.size?`${spec.cannons-state.disabledGuns.size}/${spec.cannons}`:spec.cannons;$('class-label').textContent=spec.name.toUpperCase()+' · '+spec.masts+' MAST'+(spec.masts===1?'':'S');$('wind-reading').textContent='NE · '+Math.round(seaState.wind*(10+weatherWind()*5))+' KNOTS';$('weather-label').textContent=seaState.waves>2?'TEMPEST':seaState.rain>.15?'PASSING SQUALLS':'TRADE WINDS';$('gold').textContent=state.gold.toLocaleString();$('cargo-count').textContent=`${Math.min(5,state.cargo)} / 5`;$('sunk-count').textContent=`${Math.min(2,state.sunk)} / 2`;$('salvage-objective').classList.toggle('complete',state.cargo>=5);$('battle-objective').classList.toggle('complete',state.sunk>=2);$('return-objective').classList.toggle('complete',state.status==='won');$('port-status').textContent=state.status==='won'?'✓':state.cargo>=5&&state.sunk>=2?'⚑':'—';$('hull-text').textContent=`${Math.ceil(state.hull)}%`;$('hull-bar').style.width=`${state.hull}%`;$('hull-bar').style.background=state.hull<30?'#d48662':'#b8c28e';$('speed').textContent=(Math.max(0,state.speed)*.82).toFixed(1);const angle=((state.angle%(2*Math.PI))+2*Math.PI)%(2*Math.PI);$('heading').textContent=['N','NE','E','SE','S','SW','W','NW'][Math.round(angle/(Math.PI/4))%8];$('sail-state').textContent=['Furled','Quarter','Half sail','Full sail'][state.throttle];const firing=state.salvos.filter(g=>g.owner==='player').length;$('reload-state').textContent=firing?`CREWS FIRING · ${firing} GUNS`:state.cooldown>0?`RELOADING · ${state.cooldown.toFixed(1)}s`:'CANNONS READY';$('reload-bar').style.transform=`scaleX(${1-state.cooldown/(RELOAD_TIME*upgradeEffects(state).reload)})`;const harbor=nearestHarbor(state);$('repair').hidden=!harbor||state.hull>=100&&!state.disabledGuns?.size;$('harbor-button').hidden=!harbor;if(harbor){$('harbor-button').textContent=harbor.name+' · HARBOUR [F]';$('repair').innerHTML='Repair hull · ◈ '+harbor.repairCost+' <kbd>R</kbd>';}$('coordinates').textContent=`25°${String(Math.abs(Math.round(4-state.z*.04))).padStart(2,'0')}′ N · 77°${String(Math.abs(Math.round(20-state.x*.04))).padStart(2,'0')}′ W`;drawMap($('minimap'));if($('bigmap'))drawMap($('bigmap'),true);}
function damageSmoke(model,ratio,dt){
 if(model.userData.fortModel)model=model.userData.fortModel;
 if(ratio>=.42||!model.visible)return;model.userData.smokeTimer=(model.userData.smokeTimer||0)+dt;
 if(model.userData.smokeTimer<.27)return;model.userData.smokeTimer=0;model.updateMatrixWorld(true);
 const p=model.localToWorld(new THREE.Vector3((Math.random()-.5)*1.5,model.userData.damage.fort?5:3.8,model.userData.damage.fort?5:2));
 if(p.y<-.3)return;powderSmoke.burn(p);
 if(ratio<.23)particle(p.x,p.y-.15,p.z,.1,.5,0,'#d7954c',.23,.28,'flash');
}
function handleEvents(){
 for(const e of state.events){
  if(e.type==='cannon')cannonSmoke(e);
  else if(e.type==='building-hit'||e.type==='ground-hit'){
   const point=new THREE.Vector3(e.x,e.y,e.z),direction=new THREE.Vector3(e.dx,0,e.dz).normalize();
   if(e.type==='building-hit')buildingModels.get(e.target)?.userData.damage.impact(point,debris,direction);
   else{groundScars.impact(point);debris.burst(point,{stone:true,count:20,power:.75,direction});}
   powderSmoke.impact(point,{stone:true,direction});audioEffect('hit');
  }else if(e.type==='building-destroyed'){
   buildingModels.get(e.target)?.userData.damage.destroy(debris);
   for(const dx of [-1.4,0,1.4])powderSmoke.impact({x:e.x+dx,y:e.y+.5,z:e.z},{stone:true});
   audioEffect('sunk');toast(`${e.name} collapsed.`,2);
  }
  else if(e.type==='npc-hit'){powderSmoke.impact({x:e.x,y:e.y,z:e.z},{stone:false});}
  else if(e.type==='hit'){
   const model=e.target==='player'?player:e.fort?islandModels.find((m,i)=>'fort-'+ISLANDS[i].seed===e.target):enemies.find((m,i)=>state.enemies[i].id===e.target)?.model;
   if(model)model.userData.damage.impact(new THREE.Vector3(e.x,e.y??2,e.z),debris,new THREE.Vector3(e.dx||0,0,e.dz||0).normalize());
   if(model&&!e.fort){const body=e.target==='player'?state:state.enemies.find(b=>b.id===e.target);for(const id of model.userData.damage.unsupportedGuns())disableCannon(state,body,id);}
   if(!e.collision)powderSmoke.impact({x:e.x,y:e.y??2,z:e.z},{stone:!!e.fort,direction:{x:e.dx||0,z:e.dz||0}});
  }else if(e.x!==undefined&&!['sunk','fort-silenced'].includes(e.type))burst(e.x,e.z,e.type);
  if(['cannon','hit','sunk','cargo','won','repair','fort-silenced'].includes(e.type))audioEffect(e.type==='fort-silenced'?'sunk':e.type);
  if(e.type==='colours')toast(e.navy?'Red ensign flying. Unaware patrols will let you pass; witnesses remember you.':'Hoist the colours! Unaware crews need a moment to react.',5);
  if(e.type==='gun-disabled'){const model=e.target==='player'?player:enemies.find((m,i)=>state.enemies[i].id===e.target)?.model;model?.userData.damage.disableGun(e.gun,debris);if(e.target==='player')toast('A cannon has been knocked out!',2);}
  if(e.type==='town-evacuating')toast('Townspeople are fleeing the bombardment!',3);
  if(e.type==='ship-abandoned')toast('The enemy crew is abandoning ship! Rowboats in the water.',5);
  if(e.type==='building-ignited')toast(`${e.name} stores caught fire!`,3);
  if(e.type==='cargo')toast(`Cargo recovered. +150 doubloons${state.cargo>=5?' · All cargo secured!':''}`);
  if(e.type==='sunk'){toast('Navy ship going down. +300 doubloons');const target=enemies[e.id].model;target.userData.damage.sync(0);target.userData.damage.destroy(debris);}
  if(e.type==='hit'&&!e.enemy)toast(e.collision?'Timbers struck! Hull damaged.':'We’re taking fire, Captain!',2);
  if(e.type==='reef')toast('Mind the shoals! Hull damaged.');
  if(e.type==='edge')toast('Uncharted waters. Turn back toward the islands.');
  if(e.type==='repair'){player.userData.damage.reset();toast('Repairs complete. Good as new.');}
  if(e.type==='upgrade')toast(UPGRADES[e.id].name+' fitted.');
  if(e.type==='refit')toast('Fine powder and shot acquired. Cannon damage +15%.');
  if(e.type==='fort-silenced'){toast('Royal Navy battery silenced. +400 doubloons.');const target=islandModels.find((m,i)=>'fort-'+ISLANDS[i].seed===e.id);target?.userData.damage.destroy(debris);}
  if(e.type==='won')showModal('won');
  if(e.type==='lost'){deathPending=true;keys.clear();player.userData.damage.sync(0);player.userData.damage.destroy(debris,state);toast('Abandon ship! She’s going down.',8);}
 }
 state.events.length=0;
}
